classes = {c['name']: c for c in d['classes']}

def fmt_type(t):
    if isinstance(t, str): return t
    ct = t.get('complex_type')
    if ct == 'array': return fmt_type(t['value'])+'[]'
    if ct == 'union': return ' | '.join(fmt_type(o) for o in t['options'])
    if ct == 'dictionary': return f"dict[{fmt_type(t['key'])} -> {fmt_type(t['value'])}]"
    if ct == 'literal': return repr(t['value'])
    if ct == 'type': return fmt_type(t['value'])
    if ct == 'table' or ct == 'tuple':
        return 'table{' + ', '.join(f"{p['name']}: {fmt_type(p['type'])}{'?' if p.get('optional') else ''}" for p in t.get('parameters', [])) + '}'
    if ct == 'function': return 'function'
    if ct == 'LuaStruct': return 'struct'
    return str(t)

def show_member(cls, name):
    c = classes.get(cls)
    if not c:
        print(f"{cls}: CLASS NOT FOUND"); return
    for kind in ('methods','attributes'):
        for m in c.get(kind, []):
            if m['name'] == name:
                if kind == 'methods':
                    ps = m.get('parameters', [])
                    sig = ', '.join(f"{p['name']}: {fmt_type(p['type'])}{'?' if p.get('optional') else ''}" for p in sorted(ps, key=lambda p: p['order']))
                    va = m.get('variadic_parameter')
                    if va: sig += f" ...variadic: {fmt_type(va.get('type'))}"
                    ret = ', '.join(fmt_type(r['type']) for r in m.get('return_values', []))
                    print(f"{cls}.{name}({sig}) -> {ret}")
                    tp = m.get('takes_table')
                    if tp: print(f"   takes_table={tp}")
                    desc = m.get('description','')
                    if desc: print(f"   DESC: {desc[:300]}")
                else:
                    rt = m.get('read_type'); wt = m.get('write_type')
                    print(f"{cls}.{name}: read={fmt_type(rt) if rt else None} write={fmt_type(wt) if wt else None}")
                    desc = m.get('description','')
                    if desc: print(f"   DESC: {desc[:400]}")
                return
    print(f"{cls}.{name}: MEMBER NOT FOUND")

targets = [
 ('LuaGameScript','print'), ('LuaPlayer','print'), ('LuaForce','print'), ('LuaSurface','print'),
 ('LuaGuiElement','caption'), ('LuaGuiElement','tooltip'), ('LuaGuiElement','text'),
